<?php require_once 'auth.php';requiereAdmin();$rows=$conexion->query('SELECT c.*,m.nombre mascota,u.nombre cliente FROM citas c JOIN mascotas m ON m.idMascota=c.idMascota JOIN usuario u ON u.idUsuario=c.idUsuario ORDER BY c.fecha_cita DESC,c.hora DESC')->fetchAll();encabezado('Todas las citas');?><div class="table-wrap"><table><tr><th>Cliente</th><th>Mascota</th><th>Fecha</th><th>Hora</th><th>Motivo</th><th>Estado</th><th>Respuesta</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['cliente'])?></td><td><?=e($r['mascota'])?></td><td><?=e($r['fecha_cita'])?></td><td><?=e($r['hora'])?></td><td><?=e($r['motivo'])?></td><td><?=e($r['estado'])?></td><td><?=e($r['respuesta']??'—')?></td></tr><?php endforeach;?></table></div><?php pie();?>